style.css:
@-moz-document domain("discord.com") {
/* ===== FONDOS ===== */
  body {
    --background-primary: #ffe6f0 !important;   /* Fondo principal */
    --background-secondary: #ffd6eb !important; /* Canales/servidores */
    --background-tertiary: #ffb3d9 !important;  /* Sidebar y menús */
    --background-floating: #ffe0f0 !important;  /* Popups y menús flotantes */
    --background-accent: #ff99cc !important;    /* Acentos */
  }

  /* ===== TEXTO ===== */
  body {
    --text-normal: #4d004d !important;   /* Texto normal */
    --text-muted: #800060 !important;    /* Texto apagado */
    --header-primary: #66004d !important;
    --header-secondary: #993366 !important;
    --interactive-normal: #800060 !important; /* Texto interactivo */
    --interactive-hover: #66004d !important;  /* Hover en textos */
    --interactive-active: #4d004d !important; /* Activo */
    --interactive-muted: #b36699 !important;  /* Deshabilitado */
  }

  /* ===== BOTONES ===== */
  button,
  .button-38aScr,
  .lookFilled-yCfaCM {
    background-color: #ff66b2 !important; /* Botón normal */
    color: white !important;
    border-radius: 10px !important;
  }
  button:hover,
  .lookFilled-yCfaCM:hover {
    background-color: #ff3385 !important; /* Hover */
  }

  /* ===== SCROLLBAR ===== */
  ::-webkit-scrollbar {
    width: 8px !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #ff99cc !important;
    border-radius: 4px !important;
  }
  ::-webkit-scrollbar-track {
    background-color: #ffe6f0 !important;
  }

  /* ===== MENSAJES ===== */
  .message-2CShn3 {
    background: #fff0f6 !important; 
    border-radius: 12px !important;
    padding: 4px 8px !important;
  }
  .message-2CShn3:hover {
    background: #ffe6f0 !important;
  }

  /* ===== MENCIONES ===== */
  .mention {
    background-color: #ff66b2 !important;
    color: white !important;
    border-radius: 6px !important;
    padding: 2px 4px !important;
  }

  /* ===== LISTA DE SERVIDORES ===== */
  .wrapper-1BJsBx {
    background-color: #ffb3d9 !important;
    border-radius: 15px !important;
  }
  .wrapper-1BJsBx:hover {
    background-color: #ff80bf !important;
  }

  /* ===== INPUTS ===== */
  .scrollableContainer-15eg7h {
    background-color: #ffe6f0 !important;
    border: 1px solid #ff99cc !important;
    border-radius: 12px !important;
  }
}
